请对以下 case 进行三维加权评分。

=== case_id ===
Case-06-memory-clean-110

=== 用户原始指令 (query.txt) ===
给我做个内存清理卡片嘛，文字要叠在背景图上那种，点跳到应用里，能看天气，显示已连接

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "给我做个内存清理卡片嘛，文字要叠在背景图上那种，点跳到应用里，能看天气，显示已连接",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.hmos.settings",
        "abilityName": "com.huawei.hmos.settings.MainAbility",
        "uri": "storage_settings"
      }
    }
  ],
  "dataModel": {
    "value": {
      "card": {
        "title": "内存清理",
        "status": "已连接",
        "actionText": "立即清理",
        "background": "assets/memory-clean-bg.png",
        "icon": "assets/memory-clean-icon.png"
      },
      "data": {
        "weather": {
          "location": {
            "districtName": "当前位置",
            "prefectureName": ""
          },
          "current": {
            "temperatureText": "26°C",
            "condition": "多云"
          },
          "daily": [],
          "updatedAt": ""
        }
      },
      "state": {
        "loading": false
      }
    }
  },
  "assetCandidates": [
    {
      "assetRef": "memory_clean_background",
      "src": "assets/memory-clean-bg.png",
      "use": "background image",
      "description": "内存清理卡片背景图，适合承载叠加文字和轻量状态信息。",
      "bindTo": "/card/background"
    },
    {
      "assetRef": "memory_clean_icon",
      "src": "assets/memory-clean-icon.png",
      "use": "memory cleanup icon",
      "description": "内存清理图标素材，用于表达清理、释放空间或系统优化入口。",
      "bindTo": "/card/icon"
    }
  ]
}

